// One search helper for both the villa-rental bot and the property-sales bot.
// kind = "sale"  -> searches the website's property listings (below)
// kind = "rental" (default) -> searches the Villas + Bookings sheets
const q = $('When Called by Agent').first().json;
const s = v => (v === undefined || v === null) ? '' : String(v).trim();
const num = v => { const n = Number(s(v).replace(/[^0-9.]/g, '')); return isNaN(n) ? 0 : n; };
const norm = v => s(v).toLowerCase().replace(/\s+/g, '');

// ---------- PROPERTY SALES (Chennai Prime Realty website listings) ----------
// Keep this list in sync with src/data/properties.ts in the website repo.
const LISTINGS = [
