  { id: "p4", title: "Velachery Greens", location: "Velachery, Chennai", price: "₹1.20 Cr", bhk: "2 BHK", area: "1240 sq.ft", category: "Apartments", image_url: "https://chennai-prime-reality.vercel.app/assets/property-apartment-Dyu4ijyG.jpg" },
  { id: "p5", title: "Porur Investment Plot", location: "Porur, Chennai", price: "₹85 L", bhk: "", area: "2400 sq.ft", category: "Plots", image_url: "https://chennai-prime-reality.vercel.app/assets/property-plot-CnOFuRQm.jpg" },
  { id: "p6", title: "OMR IT Park Office", location: "OMR, Chennai", price: "₹3.10 Cr", bhk: "", area: "4500 sq.ft", category: "Commercial", image_url: "https://chennai-prime-reality.vercel.app/assets/property-commercial-B-NLjFa3.jpg" },
  { id: "p7", title: "Prime Penthouse Suites", location: "Adyar, Chennai", price: "₹6.75 Cr", bhk: "4 BHK", area: "4100 sq.ft", category: "Apartments", image_url: "https://chennai-prime-reality.vercel.app/assets/property-penthouse-5NlQOx4j.jpg" },
  { id: "p8", title: "ECR Beachside Villa", location: "ECR, Chennai", price: "₹5.80 Cr", bhk: "5 BHK", area: "3800 sq.ft", category: "Villas", image_url: "https://chennai-prime-reality.vercel.app/assets/property-villa-DNn2yRY1.jpg" },
  { id: "p9", title: "Anna Nagar Commercial Hub", location: "Anna Nagar, Chennai", price: "₹4.20 Cr", bhk: "", area: "5200 sq.ft", category: "Commercial", image_url: "https://chennai-prime-reality.vercel.app/assets/property-commercial-B-NLjFa3.jpg" },
  { id: "p10", title: "Porur Garden Plots", location: "Porur, Chennai", price: "₹1.10 Cr", bhk: "", area: "3600 sq.ft", category: "Plots", image_url: "https://chennai-prime-reality.vercel.app/assets/property-plot-CnOFuRQm.jpg" },
  { id: "p11", title: "Velachery Skyline", location: "Velachery, Chennai", price: "₹1.65 Cr", bhk: "3 BHK", area: "1520 sq.ft", category: "Apartments", image_url: "https://chennai-prime-reality.vercel.app/assets/property-velachery-Bix-rIQ_.jpg" },
  { id: "p12", title: "OMR Tech Park Villa", location: "OMR, Chennai", price: "₹3.95 Cr", bhk: "4 BHK", area: "2900 sq.ft", category: "Villas", image_url: "https://chennai-prime-reality.vercel.app/assets/property-villa-DNn2yRY1.jpg" },
  { id: "p13", title: "Sholinganallur Sunset Residences", location: "Sholinganallur, Chennai", price: "₹1.45 Cr", bhk: "3 BHK", area: "1580 sq.ft", category: "Apartments", image_url: "https://images.unsplash.com/photo-1624204386084-dd8c05e32226?fm=jpg&w=1024&q=80&fit=crop" },
  { id: "p14", title: "T. Nagar Glass Arcade", location: "T. Nagar, Chennai", price: "₹7.20 Cr", bhk: "", area: "6800 sq.ft", category: "Commercial", image_url: "https://images.unsplash.com/photo-1621831337128-35676ca30868?fm=jpg&w=1024&q=80&fit=crop" },
  { id: "p15", title: "Mylapore Heritage Homes", location: "Mylapore, Chennai", price: "₹1.35 Cr", bhk: "2 BHK", area: "1180 sq.ft", category: "Apartments", image_url: "https://images.unsplash.com/photo-1501459530422-244942cf51f5?fm=jpg&w=1024&q=80&fit=crop" },
  { id: "p16", title: "Nungambakkam Sky Penthouse", location: "Nungambakkam, Chennai", price: "₹8.50 Cr", bhk: "4 BHK", area: "4600 sq.ft", category: "Apartments", image_url: "https://images.unsplash.com/photo-1776362355123-ca966d36e29c?fm=jpg&w=1024&q=80&fit=crop" },
  { id: "p17", title: "Besant Nagar Pool Villa", location: "Besant Nagar, Chennai", price: "₹6.20 Cr", bhk: "4 BHK", area: "3600 sq.ft", category: "Villas", image_url: "https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?fm=jpg&w=1024&q=80&fit=crop" },
  { id: "p18", title: "Guindy Business Centre", location: "Guindy, Chennai", price: "₹5.40 Cr", bhk: "", area: "7200 sq.ft", category: "Commercial", image_url: "https://images.unsplash.com/photo-1781919293919-693ee10fb06c?fm=jpg&w=1024&q=80&fit=crop" },
  { id: "p19", title: "Tambaram Green Acres", location: "Tambaram, Chennai", price: "₹62 L", bhk: "", area: "2400 sq.ft", category: "Plots", image_url: "https://images.unsplash.com/photo-1495107334309-fcf20504a5ab?fm=jpg&w=1024&q=80&fit=crop" },
  { id: "p20", title: "Perungudi Lakeview Towers", location: "Perungudi, Chennai", price: "₹98 L", bhk: "2 BHK", area: "1150 sq.ft", category: "Apartments", image_url: "https://images.unsplash.com/photo-1525953776754-6c4b7ee655ab?fm=jpg&w=1024&q=80&fit=crop" },
  { id: "p21", title: "Medavakkam Gated Villas", location: "Medavakkam, Chennai", price: "₹2.15 Cr", bhk: "3 BHK", area: "2200 sq.ft", category: "Villas", image_url: "https://images.unsplash.com/photo-1580587771525-78b9dba3b914?fm=jpg&w=1024&q=80&fit=crop" },
  { id: "p22", title: "Kovalam Beach Retreat", location: "Kovalam, Chennai", price: "₹7.90 Cr", bhk: "5 BHK", area: "4800 sq.ft", category: "Villas", image_url: "https://images.unsplash.com/photo-1706808849780-7a04fbac83ef?fm=jpg&w=1024&q=80&fit=crop" },
  { id: "p23", title: "Oragadam Industrial Plots", location: "Oragadam, Chennai", price: "₹1.80 Cr", bhk: "", area: "10000 sq.ft", category: "Plots", image_url: "https://images.unsplash.com/photo-1653663786108-21ca52a24171?fm=jpg&w=1024&q=80&fit=crop" },
  { id: "p24", title: "Kilpauk Garden Residency", location: "Kilpauk, Chennai", price: "₹2.05 Cr", bhk: "3 BHK", area: "1720 sq.ft", category: "Apartments", image_url: "https://images.unsplash.com/photo-1610286986642-057ece0c3656?fm=jpg&w=1024&q=80&fit=crop" },
];
const toInr = p => { const t = s(p).toLowerCase(); const n = num(t); if (t.includes('cr')) return n * 1e7; if (/\bl\b|lakh|lac/.test(t) || t.endsWith('l')) return n * 1e5; return n; };

if (s(q.kind).toLowerCase() === 'sale') {
  const cat = s(q.category).toLowerCase().replace(/s$/, '');
  const loc = s(q.location).toLowerCase();
  const bhk = num(q.bhk);
  const min = num(q.budget_min_inr), max = num(q.budget_max_inr);
  const rows = LISTINGS.map(l => {
    const why = [];
    const price = toInr(l.price);
    if (cat && !l.category.toLowerCase().startsWith(cat)) why.push('category is ' + l.category);
    if (loc && !l.location.toLowerCase().includes(loc) && !loc.includes(l.location.toLowerCase().split(',')[0])) why.push('is in ' + l.location);
    if (bhk && num(l.bhk) !== bhk) why.push(l.bhk ? 'is ' + l.bhk : 'has no BHK (plot/commercial)');
    if (max && price > max) why.push('price ' + l.price + ' is above budget');
    if (min && price < min) why.push('price ' + l.price + ' is below the budget range');
    return { ...l, price_inr: price, reasons_not_matching: why };
  });
  const matches = rows.filter(r => !r.reasons_not_matching.length).map(({ reasons_not_matching, ...r }) => r);
  const closest = matches.length ? [] : rows.sort((a, b) => a.reasons_not_matching.length - b.reasons_not_matching.length).slice(0, 3);
  const catalogue = { areas: [...new Set(LISTINGS.map(l => l.location))], categories: [...new Set(LISTINGS.map(l => l.category))], price_range: '₹62 L to ₹8.50 Cr' };
  return [{ json: { kind: 'sale', catalogue, match_count: matches.length, matches: matches.slice(0, 5), closest_alternatives: closest } }];
}

// ---------- VILLA RENTALS (Villas + Bookings sheets) ----------
// Demo photos for villas (the sheet has no photo column yet). Same villa always gets the same photo.
const VILLA_PHOTOS = ["https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?fm=jpg&w=1024&q=80&fit=crop", "https://images.unsplash.com/photo-1580587771525-78b9dba3b914?fm=jpg&w=1024&q=80&fit=crop", "https://images.unsplash.com/photo-1706808849780-7a04fbac83ef?fm=jpg&w=1024&q=80&fit=crop", "https://images.unsplash.com/photo-1613490493576-7fde63acd811?fm=jpg&w=1024&q=80&fit=crop", "https://images.unsplash.com/photo-1670589953882-b94c9cb380f5?fm=jpg&w=1024&q=80&fit=crop", "https://images.unsplash.com/photo-1757524492552-d47a66a2b63e?fm=jpg&w=1024&q=80&fit=crop", "https://images.unsplash.com/photo-1766848834872-fa8158c94a5d?fm=jpg&w=1024&q=80&fit=crop", "https://images.unsplash.com/photo-1670589953903-b4e2f17a70a9?fm=jpg&w=1024&q=80&fit=crop"];
const villaPhoto = v => s(v.Image_URL) || VILLA_PHOTOS[Math.abs([...s(v.Villa_ID)].reduce((a, ch) => a * 31 + ch.charCodeAt(0), 7)) % VILLA_PHOTOS.length];
const villas = $('Read Villas').all().map(i => i.json).filter(v => v.Villa_ID);
const bookings = $('Read Bookings').all().map(i => i.json).filter(b => b.Villa_ID);
const MON = { jan:0,feb:1,mar:2,apr:3,may:4,jun:5,jul:6,aug:7,sep:8,oct:9,nov:10,dec:11 };
function day(v) {
  const t = s(v); if (!t) return null;
  let m = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/); if (m) return Date.UTC(+m[1], +m[2]-1, +m[3]);
  m = t.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})/); if (m) return Date.UTC(+m[3], +m[2]-1, +m[1]);
  m = t.match(/^(\d{1,2})\s*([A-Za-z]{3})[A-Za-z]*\s*(\d{4})?/); if (m && MON[m[2].toLowerCase()] !== undefined) return Date.UTC(m[3] ? +m[3] : new Date().getUTCFullYear(), MON[m[2].toLowerCase()], +m[1]);
  const d = new Date(t); return isNaN(d) ? null : Date.UTC(d.getFullYear(), d.getMonth(), d.getDate());
}
const iso = d => new Date(d).toISOString().slice(0, 10);
const want = {
  type: norm(q.property_type), loc: s(q.location).toLowerCase(), guests: num(q.guests),
  budget: num(q.budget_per_night), id: s(q.villa_id).toUpperCase(),
  amen: s(q.amenities).toLowerCase().split(/[,;]+/).map(a => a.trim()).filter(Boolean),
  ci: day(q.check_in), co: day(q.check_out)
};
const nights = (want.ci !== null && want.co !== null) ? Math.round((want.co - want.ci) / 86400000) : null;
const results = villas.map(v => {
  const why = [];
  if (want.id && s(v.Villa_ID).toUpperCase() !== want.id) return null;
  if (want.type && norm(v.Property_Type) !== want.type) why.push('type is ' + s(v.Property_Type));
  if (want.loc && !s(v.Location).toLowerCase().includes(want.loc) && !want.loc.includes(s(v.Location).toLowerCase())) why.push('location is ' + s(v.Location));
  if (want.guests && num(v.Max_Guests) < want.guests) why.push('max ' + num(v.Max_Guests) + ' guests');
  if (want.budget && num(v.Nightly_Rate_INR) > want.budget) why.push('rate Rs ' + num(v.Nightly_Rate_INR) + '/night is over budget');
  const va = s(v.Amenities).toLowerCase();
  const missing = want.amen.filter(a => !va.includes(a)); if (missing.length) why.push('no ' + missing.join(', '));
  if (s(v.Booking_Status).toLowerCase() !== 'available') why.push('status is ' + s(v.Booking_Status));
  if (nights !== null) {
    if (nights < 1) why.push('check-out must be after check-in');
    const af = day(v.Available_From), at = day(v.Available_To);
    if (af !== null && want.ci < af) why.push('only available from ' + iso(af));
    if (at !== null && want.co > at) why.push('only available until ' + iso(at));
    if (nights < num(v.Minimum_Nights)) why.push('minimum ' + num(v.Minimum_Nights) + ' nights');
    const clash = bookings.find(b => s(b.Villa_ID).toUpperCase() === s(v.Villa_ID).toUpperCase() && s(b.Booked).toLowerCase().startsWith('y') && day(b.Check_In) !== null && day(b.Check_Out) !== null && day(b.Check_In) < want.co && day(b.Check_Out) > want.ci);
    if (clash) why.push('already booked for these dates');
  }
  const rate = num(v.Nightly_Rate_INR);
  return {
    villa_id: s(v.Villa_ID), villa_name: s(v.Villa_Name), location: s(v.Location), property_type: s(v.Property_Type),
    max_guests: num(v.Max_Guests), nightly_rate_inr: rate, amenities: s(v.Amenities), minimum_nights: num(v.Minimum_Nights),
    available_from: s(v.Available_From), available_to: s(v.Available_To), owner_name: s(v.Owner_Name) || 'not on file', owner_phone: s(v.Owner_Phone) || 'not on file', image_url: villaPhoto(v),
    nights, total_amount_inr: nights ? rate * nights : null, reasons_not_matching: why
  };
}).filter(Boolean);
const matches = results.filter(r => !r.reasons_not_matching.length).map(({ reasons_not_matching, ...r }) => r);
const closest = matches.length ? [] : results.sort((a, b) => a.reasons_not_matching.length - b.reasons_not_matching.length).slice(0, 3);
const avail = villas.filter(v => s(v.Booking_Status).toLowerCase() === 'available');
const catalogue = { areas: [...new Set(avail.map(v => s(v.Location)))], property_types: [...new Set(avail.map(v => s(v.Property_Type)))].sort(), guests_from: avail.length ? Math.min(...avail.map(v => num(v.Max_Guests))) : null, guests_up_to: avail.length ? Math.max(...avail.map(v => num(v.Max_Guests))) : null, villa_count: avail.length };
return [{ json: {
  kind: 'rental', catalogue,
  searched_for: { property_type: q.property_type || null, location: q.location || null, guests: want.guests || null, check_in: want.ci !== null ? iso(want.ci) : null, check_out: want.co !== null ? iso(want.co) : null, nights, budget_per_night: want.budget || null, villa_id: want.id || null },
  match_count: matches.length, matches: matches.slice(0, 5), closest_alternatives: closest
} }];
